@@ -0,0 +1,116 @@
+'use client';
+
+import Link from 'next/link';
+import Image from 'next/image';
+import { useTranslations } from 'next-intl';
+import { useQuery } from '@tanstack/react-query';
+import { ExternalLink, Image as ImageIcon, Type, Video } from 'lucide-react';
+import { UIMessage } from 'ai';
+
+import { extractSuggestedTools } from '@/utils/suggested-replies';
+
+export interface AiToolCardItem {
+  id: string;
+  name: string;
+  description: string | null;
+  slug: string | null;
+  outputType?: string;
+  backgroundImage?: string | null;
+  backgroundVideo?: string | null;
+}
+
+export interface SuggestedToolsForMessageProps {
+  message: UIMessage;
+  locale: string;
+}
+
+function outputIcon(outputType: string | undefined) {
+  switch (outputType) {
+    case 'IMAGE':
+      return <ImageIcon className="h-3.5 w-3.5" />;
+    case 'VIDEO':
+      return <Video className="h-3.5 w-3.5" />;
+    default:
+      return <Type className="h-3.5 w-3.5" />;
+  }
+}
+
+export function SuggestedToolsForMessage({
+  message,
+  locale
+}: SuggestedToolsForMessageProps) {
+  const t = useTranslations('Canvas.chat');
+  const content = message.content || '';
+  const slugs = extractSuggestedTools(content);
+
+  const { data } = useQuery<{ success: boolean; data: AiToolCardItem[] }>({
+    queryKey: ['ai-tools-by-slugs', slugs?.join(',') ?? ''],
+    queryFn: async () => {
+      const params = new URLSearchParams({
+        locale,
+        slugs: (slugs ?? []).join(',')
+      });
+      const res = await fetch(`/api/ai-tools?${params}`);
+      if (!res.ok) throw new Error('Failed to fetch tools');
+      return res.json();
+    },
+    enabled: !!slugs && slugs.length > 0
+  });
+
+  const tools = data?.data ?? [];
+  if (tools.length === 0) return null;
+
+  return (
+    <div className="mt-3 space-y-2">
+      <p className="text-xs font-medium text-muted-foreground">
+        {t('suggestedTools.title')}
+      </p>
+      <div className="flex flex-col gap-2">
+        {tools.map((tool) => {
+          const slug = tool.slug ?? tool.id;
+          const href = `/${locale}/ai-tools/${slug}`;
+          return (
+            <Link
+              key={tool.id}
+              href={href}
+              target="_blank"
+              rel="noopener noreferrer"
+              aria-label={t('suggestedTools.openInNewTab')}
+              className="relative flex items-center gap-2 rounded-lg border bg-card px-2.5 py-2 text-foreground shadow-sm hover:bg-accent/50"
+            >
+              <div className="absolute left-2 top-2 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-gray-100 text-muted-foreground">
+                {outputIcon(tool.outputType)}
+              </div>
+              <div className="relative h-12 w-12 shrink-0 overflow-hidden rounded-md bg-muted">
+                {tool.backgroundImage ? (
+                  <Image
+                    src={tool.backgroundImage}
+                    alt=""
+                    width={48}
+                    height={48}
+                    className="h-full w-full object-cover"
+                  />
+                ) : (
+                  <div className="h-full w-full bg-muted" />
+                )}
+              </div>
+              <div className="min-w-0 flex-1 flex flex-col gap-0.5">
+                <div className="flex items-center gap-1.5">
+                  <span className="text-sm font-medium text-foreground truncate">
+                    {tool.name}
+                  </span>
+                </div>
+                {tool.description && (
+                  <p className="text-xs text-muted-foreground line-clamp-2">
+                    {tool.description}
+                  </p>
+                )}
+              </div>
+              <ExternalLink className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
+            </Link>
+          );
+        })}
+      </div>
+    </div>
+  );
+}
