@@ -0,0 +1,73 @@
+'use client';
+
+import { useTranslations } from 'next-intl';
+
+import { Badge } from '@/components/ui/badge';
+import {
+  Tooltip,
+  TooltipContent,
+  TooltipPortal,
+  TooltipProvider,
+  TooltipTrigger
+} from '@/components/ui/tooltip';
+
+type TagItem = { tag: { id: string; name: string } };
+
+interface AiToolTagsCellProps {
+  tags: TagItem[];
+}
+
+export function AiToolTagsCell({ tags }: AiToolTagsCellProps) {
+  const t = useTranslations('admin.aiTools');
+
+  const tagNames = tags?.map((item) => item.tag.name) ?? [];
+  const count = tagNames.length;
+
+  if (count === 0) {
+    return <span className="text-muted-foreground">-</span>;
+  }
+
+  if (count === 1) {
+    return (
+      <Badge
+        variant="outline"
+        className="border-gray-200 bg-gray-100 text-gray-700 rounded-full whitespace-nowrap font-medium"
+      >
+        {tagNames[0]}
+      </Badge>
+    );
+  }
+
+  return (
+    <TooltipProvider delayDuration={300}>
+      <Tooltip>
+        <TooltipTrigger asChild>
+          <div className="inline-block">
+            <Badge
+              variant="outline"
+              className="border-gray-200 bg-gray-100 text-gray-700 rounded-full cursor-help hover:bg-gray-200 whitespace-nowrap font-medium"
+            >
+              {count} {t('tagsCount')}
+            </Badge>
+          </div>
+        </TooltipTrigger>
+        <TooltipPortal>
+          <TooltipContent
+            side="top"
+            align="center"
+            className="max-w-xs z-[9999]"
+            sideOffset={5}
+          >
+            <div className="space-y-1">
+              {tagNames.map((name) => (
+                <div key={name} className="text-xs">
+                  • {name}
+                </div>
+              ))}
+            </div>
+          </TooltipContent>
+        </TooltipPortal>
+      </Tooltip>
+    </TooltipProvider>
+  );
+}
