+//#region Background Processing Helpers
+
+/**
+ * Waits for the imageGenerationComplete event to get imageIds for a specific generation.
+ * This is needed for Gemini/GPT models where background processing (S3 upload, Image record creation)
+ * happens asynchronously after the initial generation response.
+ *
+ * @param imageGenerationId - The ID of the image generation to wait for
+ * @param timeout - Maximum time to wait in milliseconds (default: 30000ms)
+ * @returns Promise resolving to imageIds array, or null if timeout/error occurs
+ */
+function waitForImageIds(
+  imageGenerationId: string,
+  timeout: number = 30000
+): Promise<string[] | null> {
+  return new Promise((resolve) => {
+    if (typeof window === 'undefined') {
+      resolve(null);
+      return;
+    }
+
+    const timeoutId = setTimeout(() => {
+      window.removeEventListener(
+        'imageGenerationComplete',
+        handler as EventListener
+      );
+      logger.warn('waitForImageIds timeout', {
+        imageGenerationId,
+        timeout
+      });
+      resolve(null);
+    }, timeout);
+
+    const handler = (
+      event: CustomEvent<{
+        imageGeneration: { id: string };
+        imageIds: string[];
+      }>
+    ) => {
+      if (event.detail.imageGeneration.id === imageGenerationId) {
+        clearTimeout(timeoutId);
+        window.removeEventListener(
+          'imageGenerationComplete',
+          handler as EventListener
+        );
+        logger.info('waitForImageIds received imageIds', {
+          imageGenerationId,
+          imageIdsCount: event.detail.imageIds?.length ?? 0
+        });
+        resolve(event.detail.imageIds);
+      }
+    };
+
+    window.addEventListener(
+      'imageGenerationComplete',
+      handler as EventListener
+    );
+  });
+}
